/* Generated by the module split. See README §開発の分担. */
import * as THREE from 'three';
import { DISTRICTS } from './districts.data.js';


/* ============================================================
   1b. layout engine — the reason a new district is cheap to add
   ------------------------------------------------------------
   Districts declare how much room they need (w × d), which lane they sit
   in, and what they hang off. Nothing above is an absolute coordinate.
   Everything downstream — camera fit, minimap bounds and colours, the
   particle stage boundaries, the Shield overlay — is derived from this,
   so appending a district does not require touching another number.

     lane: 'flow'   on the syscall→alert axis, laid out west→east in order
           'north'  behind the flow band  (-z), anchored to `after`
           'south'  in front of it        (+z), anchored to `after`
     y:            elevation, for decks that float over the city
     dx:           x nudge relative to the anchor district
     cam:          optional hand-tuned camera; derived if omitted
   ============================================================ */
const FLOW_X0 = -84, FLOW_GAP = 8, LANE_PAD = 10, BOX_PAD = 5;
/* read by homeView in scene.js; set by the campaign when it takes over the view */
export let campaignView = false;
export const setCampaignView = v => { campaignView = v; };
const byId = id => DISTRICTS.find(d => d.id === id);
const isFlow = d => !d.lane || d.lane === 'flow';

function layout(){
  let x = FLOW_X0;
  const flow = DISTRICTS.filter(isFlow);
  for(const d of flow){
    d.x0 = x;         d.x1 = x + d.w;
    d.z0 = -d.d/2;    d.z1 = d.d/2;
    x = d.x1 + FLOW_GAP;
  }
  /* one shared setback for every off-flow lane, so annexes line up */
  const band = Math.max(...flow.map(d => d.d)) / 2;
  for(const d of DISTRICTS){
    if(isFlow(d)) continue;
    const host = byId(d.after) || flow[0];
    d.x0 = host.x0 + (d.dx || 0);
    d.x1 = d.x0 + d.w;
    const zc = (d.lane === 'south' ? 1 : -1) * (band + LANE_PAD + d.d/2);
    d.z0 = zc - d.d/2;
    d.z1 = zc + d.d/2;
  }
  for(const d of DISTRICTS){
    d.y  = d.y || 0;
    d.cx = (d.x0 + d.x1)/2;
    d.cz = (d.z0 + d.z1)/2;
    /* A serviceable 3/4 view of this district, if none was hand-picked.
       Flow districts are approached from the south, because nothing stands
       between them and the viewer. Off-flow lanes cannot be: the flow band is
       in the way, and it gets deeper as the node count goes up. So they are
       approached from the west instead, which stays clear at any node count
       and needs no hand-tuned coordinate to follow the layout. */
    if(!d.cam) d.cam = isFlow(d)
      ? [d.cx - d.w*0.9,          d.y + d.top + 26, d.cz + d.d*1.15 + 26]
      : [d.x0 - d.w*0.75 - 18,    d.y + d.top + 30, d.cz + d.d*0.9];
  }
}
layout();

/* the city's extent, for the home-shot fit and the minimap */
function cityBox(){
  const b = new THREE.Box3();
  const v = new THREE.Vector3();
  for(const d of DISTRICTS){
    b.expandByPoint(v.set(d.x0 - BOX_PAD, 0, d.z0 - BOX_PAD));
    b.expandByPoint(v.set(d.x1 + BOX_PAD, d.y + d.top + 6, d.z1 + BOX_PAD));
  }
  return b;
}
const hex6 = n => '#' + n.toString(16).padStart(6, '0');

/* where the particle simulation changes behaviour, in district terms */
const ST = {};
(function stages(){
  const wl=byId('workloads'), dr=byId('driver'), rg=byId('ring'), st=byId('state'),
        ru=byId('rules'),     ou=byId('outputs'), pl=byId('plugins'), sd=byId('sysdig');
  ST.start    = wl.x0 + 4;
  ST.driver   = dr.cx;
  ST.ringIn   = rg.x0 + 1;
  ST.ringOut  = rg.x1 - 1;
  ST.state    = st.cx;
  ST.rulesIn  = ru.x0 + 1;
  ST.rulesOut = ru.x1 - 1;
  ST.out      = ou.cx;
  ST.end      = ou.x1 + 9;
  ST.pluginX  = pl.x0;
  ST.pluginZ  = pl.cz;
  ST.joinZ    = -12;                       // where the bypass lane merges
  ST.skyX     = sd.cx - 8;
  ST.skyY     = sd.y + 2;
  ST.skyZ     = sd.cz;
})();

export {
  DISTRICTS,
  FLOW_X0,
  FLOW_GAP,
  LANE_PAD,
  BOX_PAD,
  byId,
  isFlow,
  layout,
  cityBox,
  hex6,
  ST
};
